    // BEGIN GUIDE TRANSLATIONS
    guide_text_260313e4ac64571f: "{name_a} وہ عوامی ریکارڈ جمع کرتا ہے جو نیویارک شہر کے ادارے پہلے ہی شائع کرتے ہیں — معاہدے، اراضی کے استعمال کی درخواستیں، قواعد، اجلاس، سول سروس امتحانات اور ان سے وابستہ ادارے اور تنظیمیں — اور ہر ریکارڈ کو اس کے اصل سرکاری ماخذ سے منسلک رکھتا ہے۔",
    guide_text_641498d11bf44328: "اگر آپ پہلی بار آئے ہیں تو پہلے سبق سے شروع کریں۔ اس میں ایک حقیقی تلاش استعمال ہوتی ہے اور تقریباً دس منٹ لگتے ہیں؛ اسے مکمل کرنے کے لیے اکاؤنٹ یا ای میل پتے کی ضرورت نہیں۔ اگلے دو اسباق ایک شائع شدہ نوٹس سے اس کی بنیاد بننے والے قانون تک، اور ایک ادارے سے اس تنظیم کے ذریعے جسے وہ ادائیگی کرتا ہے، ایک ایوارڈ تک جاتے ہیں۔",
    guide_text_65173c70d8e1e737: "اگر آپ کے ذہن میں پہلے ہی کوئی کام ہے تو براہ راست طریقۂ استعمال میں جائیں۔ اگر کسی ریکارڈ کے مطلب پر سوال ہو یا کوئی نیا لفظ ملے تو فہم اور حوالہ کے حصے پہلے کوئی سبق مکمل کیے بغیر جواب دیتے ہیں۔",
    guide_text_f28a7d73644b0422: "اسباق۔ ایک حقیقی مثال کے ذریعے رہنمائی، تاکہ اختتام پر آپ صرف ایک بٹن کا کام نہیں بلکہ پورے سفر کا طریقہ جانیں۔",
    guide_text_b4074d9152312c1c: "آپ کے ذہن میں موجود کام کے لیے مختصر ہدایات، ان لیبلوں کے ساتھ جو واقعی نظر آئیں گے۔",
    guide_text_78273bdd4958a269: "ریکارڈ کیا بتاتا ہے، کیا نہیں بتاتا اور ڈیٹا کی حدود کہاں ہیں، اس کا پس منظر۔",
    guide_text_ea655ad159977ecf: "کام کے دوران رجوع کرنے کے لیے تعریفیں، کنٹرول اور کوریج۔",
    guide_text_fc81d74c51395819: "ہر مضمون پر وہ تاریخ درج ہے جب کسی مدیر نے آخری بار اسے چلتی ہوئی سائٹ سے ملا کر دیکھا۔ یہ تاریخ جانچ کے بعد ہاتھ سے لکھی جاتی ہے؛ سائٹ دوبارہ بننے پر نہیں بدلتی۔",
    guide_text_d2871a9838a24e99: "رہنما پڑھنے کے لیے زبان منتخب کریں۔ ترجمے میں کنٹرولوں کے وہی نام استعمال ہوتے ہیں جو {name_a} کے باقی حصوں میں ہیں۔ سرکاری نام، شناخت کنندے اور ماخذ سے اقتباسات اپنی اصل زبان میں رہتے ہیں۔",
    guide_text_0b1c918dea55487f: "یہاں کچھ غلط یا غائب ہے؟ [تعارف کے صفحے پر رائے کا فارم]({link_a}) دیکھ بھال کرنے والوں تک پہنچتا ہے اور اسے اکاؤنٹ کی ضرورت نہیں۔",
    guide_text_b50e208649012afa: "مرحلہ 1 — تعلق کی تفصیلات کھولیں",
