    guide_text_ee8495ba9454ba1b: "اسی لیے {name_a} پر کمیونٹی بورڈ چننے کے دو قدم ہیں — بورو، پھر نمبر — جبکہ سٹی کونسل ضلع ایک قدم لیتا ہے۔ تنہا بورڈ نمبر بورڈ کی شناخت نہیں کرتا۔",
