    guide_text_e4019615c79671ac: "**خالی صفر نہیں۔** کچھ شائع نہ ملنے کا مطلب {name_a} کے پڑھے ذرائع میں کچھ نہیں ملا، جو کچھ نہ ہونے سے الگ دعویٰ ہے۔",
    guide_text_a3af5efdba3d0af5: "**بند مدت دعوت نہیں۔** گزری تبصرے یا درخواست مدت طریقۂ کار اب بھی سکھاتی ہے، لیکن اس پر عمل نہیں کر سکتے۔",
    guide_text_b81284c95c861fac: "**اندازہ آخری تاریخ نہیں۔** {name_a} جہاں معمول کی مدت دکھاتا ہے وہ پچھلے ریکارڈ سے ہے، کبھی سرکاری تاریخ نہیں۔",
    guide_text_8b5342f71c23397b: "**شائع نتیجہ نہ ہونا مخالف فیصلہ نہیں۔** کئی کارروائیاں واقعے کے بہت بعد نتیجہ شائع کرتی ہیں، اور کچھ کبھی ایسی شکل میں نہیں جو آپ کے ریکارڈ سے جڑ سکے۔",
