    guide_text_45ca554361b0518c: "Parks کا ایک دن تک چھنا صفحہ کھولیں",
    guide_text_b386e5f51e61a27c: "ریکارڈ جمع اور برآمد کریں · {name_a}",
    guide_text_b693f56dc74c7da5: "حقیقی ریکارڈ ایک تحقیق میں پن کریں، نوٹ لگائیں، فائل لے جائیں اور عین جانیں ہر نقل کہاں رہتی اور کون پڑھ سکتا ہے۔",
    guide_text_416f08760b272d47: "ریکارڈ پن کریں، نوٹ محفوظ کریں اور مقامی برآمد یا شیئر نقل میں انتخاب کریں۔",
    guide_text_efe9f737d26c9c36: "ہر کنٹرول کیا کرتا اور آپ کو کیا ملتا ہے",
    guide_text_eaffe7e0f637492c: "اپنی تحقیق کھولیں",
    guide_text_74c74f1cc51aa393: "بجٹ درخواست اور اس کا جواب پڑھیں · {name_a}",
    guide_text_b0f275d69c7da30a: "اپنے کمیونٹی بورڈ کی بجٹ درخواست ڈھونڈیں، مؤرخہ جواب ترتیب سے پڑھیں اور بدلے جواب کو بدلے بجٹ لیبل سے الگ کریں۔",
    guide_text_dfb0fb39ac572a1a: "کمیونٹی بورڈ کی ایک بجٹ درخواست ڈھونڈیں، شائع جواب ترتیب سے پڑھیں اور بدلے جواب اور بدلے بجٹ لیبل میں فرق کریں۔",
    guide_text_60bb53de31912624: "تاریخیں اور غائب معلومات",
    guide_text_a117baa8098aee95: "کمیونٹی بورڈ ڈائریکٹری",
    guide_text_b3ccd979e1c42d7c: "Register of Community Board Budget Requests، New York City Office of Management and Budget کی اشاعت",
    guide_text_87ef59bf2711776c: "اس رہنما کی استعمال کردہ درخواستیں کھولیں",
    guide_text_dfac8dd5087e82b6: "{name_a} کی اصطلاحوں کی فرہنگ · {name_b}",
    guide_text_37429c42a853b0bc: "{name_a} پر نیویارک شہر کے عوامی ریکارڈ پڑھتے ہوئے ملنے والی اصطلاحوں، شناخت کنندوں اور اداروں کی تعریفیں، ساتھ جہاں ہر ایک آتا ہے۔",
    guide_text_395c88ebbaab3f7e: "{name_a} پر ریکارڈ پڑھتے ہوئے ملنے والے الفاظ، شہر اور اس سائٹ کے استعمال والے معنی میں۔",
    guide_text_af7e0253b519e305: "سول سروس امتحان دیں، Department of Citywide Administrative Services",
    guide_text_66b65b6fc9e1f4eb: "کنٹرول اور نتائج · {name_a}",
    guide_text_984b18097f637dce: "{name_a} کا ہر کنٹرول استعمال پر کیا کرتا ہے — تلاش، چھانٹی، پیروی، تقویم، لنک اور برآمد — اور کس حالت میں آپ رہتے ہیں۔",
    guide_text_cc0c6126eab81bfe: "عام کنٹرول، اثرات اور ان کی پیدا کردہ فائلوں یا لنک کا حوالہ دیکھیں۔",
    guide_text_02129d3d57d1a403: "{name_a} کے عوامی اینڈ پوائنٹ اور اصل ڈیٹا",
    guide_text_9e71ffac94ec5aed: "ماخذ اور کوریج · {name_a}",
    guide_text_86afc28bd1adc3a6: "{name_a} وہی دوبارہ شائع کرتا ہے جو نیویارک شہر پہلے شائع کرتا ہے۔ یہاں ریکارڈ کے ذرائع، ان کی تازگی اور خارج چیزیں ہیں۔",
    guide_text_4215da671897f7b6: "{name_a} کون سے ناشر پڑھتا ہے، ان کے ریکارڈ کتنے تازہ ہیں اور اس کی دکھانے کی حد سے باہر کیا ہے۔",
    guide_text_f63f2ac39257a767: "NYC Open Data پر City Record Online",
    guide_text_a710071dc596e7ac: "{name_a} کا شائع کردہ مکمل ماخذ رجسٹر",
    guide_text_905b214f07150804: "شہر کے ریکارڈ میں رہائش دریافت کریں · {name_a}",
    guide_text_c4fa2c24b31afece: "{name_a} کی ایک حقیقی تلاش میں رہنمائی — نتائج کے گروپ پڑھیں، دو کھولیں، ریکارڈ سرکاری ماخذ سے جانچیں اور لنک رکھیں۔",
    guide_text_513265273fc2a167: "رہائش تلاش کریں، دو قسم کے ریکارڈ موازنہ کریں اور نتیجہ سرکاری ماخذ پر جانچیں۔",
    guide_text_929738a46347d03c: "موضوعات کی پیروی اور اپ ڈیٹ حاصل کریں",
    guide_text_f7a8f5af18df98f2: "{name_a} اور اس کے ریکارڈ کے ذرائع کے بارے میں",
    guide_text_d4f4f673294624a5: "یہ تلاش خود آزمائیں",
    guide_text_7b02271132b41d51: "نوٹس سے اس کے قانونی فرض تک پہنچیں · {name_a}",
    guide_text_aa20859d12b4801b: "Sanitation کے ایک حقیقی قاعدے کو شہر کے شائع نوٹس سے پیچھے چارٹر کی ذمہ داری تک دیکھیں اور جانیں شائع ریکارڈ کہاں رکتا ہے۔",
    guide_text_fed184793dbbaadd: "Sanitation قاعدہ نوٹس سے قانونی فرض، ماخذ قانون اور اشاعت کے ثبوت تک جائیں۔",
