    guide_text_ded6d4a7ad78ff4d: "ایوارڈ کی پیروی کریں اور راستہ رکھیں · {name_a}",
    guide_text_bbaa30f2f1d16186: "شہر کے ادارے سے اس تنظیم تک جائیں جسے وہ ادائیگی کرتا ہے، پھر ایک ایوارڈ تک، اور دو قدمی مکمل راستہ خود دوبارہ بننے والے لنک کے طور پر رکھیں۔",
