    public_input_explainer_open: "عوامی رائے کیسے کام کرتی ہے",
    public_input_explainer_what_html: "<p>کسی عوامی کارروائی میں شریک ہونے کا مطلب ہے سرکاری ریکارڈ میں کچھ درج کرانا: سماعت میں بات کرنا، یا شائع شدہ آخری تاریخ سے پہلے تحریری رائے بھیجنا۔ اس ریکارڈ کا آگے کیا کردار ہوگا، یہ کارروائی پر منحصر ہے، اور اس سائٹ کی ہر فہرست بتاتی ہے کہ اس پر کون سا لاگو ہوتا ہے۔</p>",
    public_input_explainer_destinations_heading: "آپ کی بات آخرکار کہاں جاتی ہے",
    public_input_explainer_destinations_html: "<ul><li><b>عوامی آراء کا ریکارڈ</b> — رائے دہی کی مدت میں جمع کرائی گئی تحریری رائے اُس ریکارڈ میں شامل ہوتی ہے جس پر ادارے کو غور کرنا لازم ہے۔</li><li><b>سماعت کی گواہی</b> — سماعت میں آپ جو کہتے ہیں وہ اُس سماعت کے گواہی ریکارڈ میں شامل ہوتا ہے۔</li><li><b>لفظی روداد</b> — بعض کارروائیاں اجلاس کی لفظ بہ لفظ روداد شائع کرتی ہیں۔</li><li><b>کارروائی کا خلاصہ</b> — دیگر ادارے اس کے بجائے جو ہوا اُس کا خلاصہ شائع کرتے ہیں۔</li><li><b>فیصلے کی دستاویز</b> — ایک الگ ریکارڈ، جو ادارہ فیصلہ درج کرنے پر شائع کرتا ہے۔</li></ul><p>بعض کارروائیاں موصول آراء کا جواب دیتی ایک رپورٹ بھی شائع کرتی ہیں۔ یہ انہی منزلوں میں سے ایک ہے، اور ہر فہرست بتاتی ہے کہ آیا یہ لاگو ہوتی ہے۔</p>",
    public_input_explainer_limits_heading: "شرکت کی حدود",
    public_input_explainer_limits_html: "<p>کسی افسر کا جواب ریکارڈ میں اندراج سے الگ چیز ہے۔ رائے جمع کرانا یا گواہی دینا آپ کے الفاظ ریکارڈ پر لے آتا ہے، اور کوئی افسر آپ کو ذاتی طور پر جواب دینے کا پابند نہیں۔ یہ سائٹ ایسے کسی جواب کا وعدہ نہیں کرتی۔</p><p>آراء کی گنتی محض گنتی ہی رہتی ہے۔ ادارہ جو کچھ کہا گیا اُسے اُس قانون کی روشنی میں پرکھتا ہے جس کے تحت وہ کام کرتا ہے، اس لیے یہ سائٹ کسی بھی مجموعی تعداد کو حمایت یا مخالفت کے طور پر پیش نہیں کرتی اور آراء کی مقدار کو ووٹ نہیں سمجھتی۔</p>",
    public_input_explainer_examples_heading: "عملی طور پر یہ تین طرح سے کام کرتا ہے",
    public_input_explainer_example_hearing: "کسی بل پر سٹی کونسل کی سماعت میں بات کریں، یا تحریری گواہی بھیجیں۔",
    public_input_explainer_example_hearing_surface: "طے شدہ سماعتیں اور اجلاس دیکھیں",
    public_input_explainer_example_rule: "کسی ادارے کے مجوزہ ضابطے پر اُس کی شائع شدہ آخری تاریخ سے پہلے رائے دیں۔",
    public_input_explainer_example_rule_surface: "ضابطوں پر کھلی رائے دہی کی مدتیں دیکھیں",
    public_input_explainer_example_contract: "کسی مجوزہ ٹھیکے کے ایوارڈ پر رائے دہی کی مدت کے دوران رائے دیں۔",
    public_input_explainer_example_contract_surface: "ٹھیکوں پر رائے دہی کی آخری تاریخیں دیکھیں",
    public_input_explainer_official_source: "سرکاری ماخذ: {source}",
    public_input_explainer_method_summary: "یہ وضاحت کہاں سے آئی ہے",
    public_input_explainer_method_html: "<p>اوپر کی ہر مثال اُس شہری صفحے سے جُڑی ہے جو اُسے چلاتا ہے، اور اس سائٹ کے اُس حصے سے بھی جہاں اُس قسم کے موجودہ ریکارڈ درج ہیں۔ یہ وضاحت بتاتی ہے کہ ایسی کارروائیاں عام طور پر کیسے چلتی ہیں۔ کسی ایک کی مخصوص تاریخ، حیثیت، مقصد اور شرکت کا راستہ اُسی کی اپنی فہرست پر رہتا ہے، اُس کے City Record ماخذ لنک کے ساتھ۔</p>",
