    about_p_what_html: "CityScroll آپ کو یہ جاننے میں مدد دیتا ہے کہ نیو یارک شہر کی حکومت میں کیا ہو رہا ہے اور آپ آگے کیا کر سکتے ہیں۔ فوری تاریخوں کے لیے <b>ابھی</b>، مقامی تبدیلیوں کے لیے <b>آپ کے قریب</b>، محفوظ نگرانیوں کے لیے <b>پیروی</b>، یا ٹھیکوں اور منصوبوں، زمین کے استعمال، اجلاسوں اور ووٹوں، ملازمت کے امتحانات، شہری املاک کی فروخت اور قواعد کے لیے <b>براؤز</b> سے شروع کریں۔ <b>رہنما</b> سے ریکارڈ پڑھنا سیکھیں۔ یہ شہر کی سرکاری اشاعتوں سے بنایا گیا ہے، مگر آزاد ہے اور نیو یارک شہر اسے نہ چلاتا ہے نہ اس کی توثیق کرتا ہے۔",
    about_h_content: "ہمارے مواد کے بارے میں",
    about_p_content_html: "CityScroll عنوانات اور سادہ زبان میں وضاحتوں کے مسودے بنانے کے لیے تخلیقی مصنوعی ذہانت استعمال کرتا ہے۔ مواد شائع ہونے سے پہلے ایک انسان اس کا جائزہ لے کر تدوین کرتا ہے۔ مصنوعی ذہانت سائٹ پر دکھائے گئے سرکاری ریکارڈ نہ بناتی ہے نہ بدلتی ہے۔",
    about_h_flags: "نشانات اور سیاق و سباق، وضاحت کے ساتھ",
    about_h_tax_lien_formula:"Tax lien sale progression",
    about_p_tax_lien_formula_html: "CityScroll دکھاتا ہے کہ اسی مرحلے کے ٹیکس حقِ حبس پچھلے ادوار کی آخری فروخت فہرست تک کتنی بار پہنچے۔ یہ پیش گوئی نہیں کرتا کہ جائیداد فروخت یا ضبط ہوگی۔",
    about_p_flags_intro_html: "خریداری کے نوٹسز دو قسم کے حساب شدہ نوٹس رکھتے ہیں۔ دونوں <b>شماریاتی سیاق و سباق ہیں، نتائج یا الزام نہیں</b>۔ ایک نشان صرف اس بات کا مطلب ہے کہ \"قریب سے دیکھنے کے قابل ہے\"۔ ہر فارمولے کے پیچھے ایک منصفانہ وجہ ہے۔ ایمرجنسیاں واقعی ہوتی ہیں۔ کچھ منڈیاں خصوصی ہیں اور ان میں بولی دہندگان کم ہیں۔ نام کی مماثلت مکمل نہیں ہے۔ یہ طریقہ کار دو رہنما اصولوں پر عمل کرتا ہے۔ ایک ہے <a href=\"https://www.open-contracting.org/resources/red-flags-in-public-procurement-a-guide-to-using-data-to-detect-and-mitigate-risks/\" target=\"_blank\" rel=\"noopener noreferrer\">اوپن کانٹریکٹنگ پارٹنرشپ کی ریڈ فلیگز گائیڈ<span class=\"sr-only\"> (نئے ٹیب میں کھلتا ہے)</span></a>۔ دوسرا ہے <a href=\"https://opentender.eu/\" target=\"_blank\" rel=\"noopener noreferrer\">Opentender<span class=\"sr-only\"> (نئے ٹیب میں کھلتا ہے)</span></a> کے دیانتداری کے اصول۔",
    about_li_flags_html: "<li><b>⚑ مختصر اشتہاری وقفہ</b> — نوٹس پوسٹ ہونے اور جواب کی آخری تاریخ کے درمیان دنوں کی تعداد۔ ہم اسے نشان زد کرتے ہیں جب یہ 10 دن یا کم ہو اور ادارے کی اپنی درمیانی مدت کے نصف سے کم ہو۔ درمیانی مدت اس ادارے کے آخری 200 نوٹسز سے آتی ہے۔ مختصر وقفے ان لوگوں کے حق میں جاتے ہیں جو پہلے ہی جانتے تھے کہ کام آنے والا ہے۔</li><li><b>⚑ غیر مسابقتی طریقہ</b> — نوٹس کہتا ہے کہ مکمل مقابلے کے بغیر ایک وینڈر منتخب کیا جائے گا۔ یہ بات چیت کے ذریعے کیا گیا معاہدہ، ایک منتخب واحد ذریعہ، فوری خریداری، یا ایک آزمائشی پروجیکٹ ہو سکتا ہے۔ یہ کبھی کبھی منصفانہ ہو سکتا ہے۔ لیکن اس کے بارے میں جاننا ہمیشہ اچھا ہے۔</li><li><b>⚑ بار بار کے ایوارڈز</b> — ایک ہی وینڈر کا نام 90 دنوں کے اندر اسی ادارے میں 3 یا اس سے زیادہ ایوارڈ نوٹسز میں ظاہر ہوتا ہے۔ یہ اتنا ہی جانبداری کی طرف اشارہ کر سکتا ہے جتنا کہ ایک بلینکٹ ٹھیکے کے تحت ٹاسک آرڈرز کی طرف۔ نشان صرف انہیں شمار کرتا ہے — آپ فیصلہ کرتے ہیں کہ اس کا کیا مطلب ہے۔</li><li><b>سیاق و سباق کی پٹی</b> — ایک ایوارڈ کتنا بڑا ہے، جو پچھلے 12 مہینوں میں اس ادارے کے ایوارڈز کے فیصد کے طور پر دکھایا جاتا ہے (صرف اس وقت دکھایا جاتا ہے جب ادارے کے پاس اس مدت میں 20 یا اس سے زیادہ ایوارڈز ہوں)۔ یہ اسی مدت میں ادارے کی ایوارڈ رقم میں وینڈر کا حصہ بھی دکھاتا ہے۔ ہم بالکل شائع شدہ نام استعمال کرتے ہیں۔ ہم یہاں نام کی مختلف شکلوں کو یکجا نہیں کرتے۔</li><li><b>قواعد کی منظوری میں تاخیر (تخمینہ)</b> — تبصرے کی مدت بند ہونے کے بعد، ملتی جلتی Agency Rules تاریخی طور پر Notice of Adoption تک کتنے عرصے میں پہنچیں۔ City Record کی تاریخ سے، right-censoring کے ساتھ تاکہ نامکمل عمل اصل سے تیز نہ دکھیں۔ کم از کم ۲۰ ماضی کے وقفے ہوں تو ادارے کے لحاظ سے، ورنہ پورے شہر کا۔ قواعد کی ٹائم لائن پر ڈیش والا “Estimate” حصہ اور صرف بینڈ تبدیلی پر ڈائجسٹ کی ایک لائن — کبھی تصدیق شدہ تاریخ نہیں۔ مکمل فارمولا: <a href=\"https://github.com/cityscroll/cityscroll-app/blob/main/docs/formulas/rules-adoption-lag.md\">rules adoption lag</a>.</li>",
    about_p_flags_footer_html: "جب آپ نوٹس دیکھتے ہیں تو تمام اعداد <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">City Record Open Data<span class=\"sr-only\"> (نئے ٹیب میں کھلتا ہے)</span></a> سے براہ راست آتے ہیں۔ یہ ایوارڈز <b>جیسا کہ شائع ہوئے</b> ہیں۔ اعداد ٹھیکے کے اندراج اور حقیقی ادائیگی سے پیچھے رہ سکتے ہیں۔ یہاں کچھ بھی یہ نہیں کہتا کہ کسی نے غلط کیا۔ یہ صرف آپ کو حساب کتاب سے بچاتا ہے۔",
