    api_p_agencies_limits: "مطابقت میں حروف کی صورت، رموزِ اوقاف، معروف مختصر نام اور انتظامی خاندان استعمال ہوتے ہیں۔ فہرست کی تازہ کاری تک نئے ہجے کو الگ شناختی نمبر مل سکتا ہے۔ یہ فہرست ریکارڈ جوڑنے میں مدد دیتی ہے؛ یہ اداروں کی سرکاری رجسٹری نہیں ہے۔",
    api_h_batch: "بیچ کراس ریفرنس",
