    api_h_sharedinv: "شیئر شدہ تحقیقات",
    api_p_sharedinv_html: "<code>POST /inv</code> ایک پن لسٹ کا سنیپ شاٹ محفوظ کرتا ہے (صرف ساختی فیلڈز، ≤32KB، 90 دن TTL، 10/دن/IP) اور ایک ID واپس کرتا ہے۔ <code>GET /inv/&lt;id&gt;</code> اسے واپس پڑھتا ہے۔ سائٹ انہیں <code>/#investigation/shared/&lt;id&gt;</code> پر رینڈر کرتی ہے۔",
    api_h_stats: "عوامی اعداد و شمار",
    api_p_stats_html: "<code>GET /stats</code> — پیش کردہ مصنوعات کا احاطہ بطور مجموعی گنتی (حصے کے اعتبار سے ریکارڈ سیٹ، ہر ایک کے ساتھ اس کی ریکارڈ قسم، شمار کا اصول اور اپنی شواہد کی تاریخ)۔ یہ تقریباً 15 منٹ کیشڈ ہے۔ قابلِ مطالعہ ورژن: <a href=\"stats.html\">اعداد و شمار</a>۔ متعلقہ: ڈائجسٹ ای میلز نوٹسز کو <code>GET /r/&lt;kind&gt;/&lt;request_id&gt;</code> کے ذریعے لنک کرتی ہیں، جو ID کو معلوم نوٹسز سے تصدیق کرتا ہے، متعلقہ مستقل لنک تک ری ڈائریکٹ کرتا ہے، اور روزانہ ایک عدد ریکارڈ کرتا ہے۔",
    api_h_subscribe: "ای میل کے ذریعے سبسکرائب کریں",
    api_p_subscribe_html: "<a href=\"mailto:subscribe@crol-list.org\"><code>subscribe@crol-list.org</code></a> کو ای میل کریں اور سادہ انگریزی میں بیان کریں کہ آپ کیا چاہتے ہیں — مثال کے طور پر، \"$500k سے زیادہ کے تعمیراتی ٹھیکے کے ایوارڈز\" یا \"Brooklyn میں دوبارہ زوننگ کے نوٹسز\"۔ درخواست پر کارروائی ہوتے ہی نگرانی شروع ہو جاتی ہے۔ خیرمقدمی ای میل میں بتایا جاتا ہے کہ کیا مانیٹر کیا جائے گا اور انتظام و رکنیت ختم کرنے کے ایک کلک والے لنکس شامل ہوتے ہیں۔ روزانہ کی حدیں لاگو ہوتی ہیں۔",
    api_h_mcp: "MCP — AI اسسٹنٹس کے لیے",
    api_p_mcp_html: "<code>POST /mcp</code> (Streamable HTTP، JSON-RPC) — کسی MCP کلائنٹ کو <code>https://api.cityscroll.org/mcp</code> پر پوائنٹ کریں۔ اوزار: <code>search_notices</code> اور <code>get_notice</code> (روزانہ تازہ ہونے والا نوٹسز کا آئینہ، ایمانداری کے اصولوں کے ساتھ)، <code>preview_watch</code> (سادہ انگریزی ← ایک مستقل نگرانی سبسکرائب کیے بغیر کیا فراہم کرے گی)، اور <code>create_watch</code> (سادہ انگریزی ← نگرانی فوراً شروع ہو جاتی ہے اور خیرمقدمی ای میل میں اس کا دائرہ بتایا جاتا ہے)۔ نگرانی کا انتظام ای میل شدہ انتظام اور رکنیت ختم کرنے کے لنکس کے پیچھے رہتا ہے — کوئی پتہ جاننا کبھی بھی اس کی سبسکرپشنز کو ظاہر یا کنٹرول نہیں کرتا۔ فی IP اور روزانہ ماڈل کال کی حدیں لاگو ہوتی ہیں۔",
    api_h_upstream: "بالادست ڈیٹا",
    api_p_upstream_html: "CityScroll عوامی ڈیٹا سیٹس کو دوبارہ شائع اور یکجا کرتا ہے — بڑے پیمانے پر کام کے لیے، براہ راست ماخذ پر جائیں: <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">City Record Online (dg92-zbpx، Socrata SODA)<span class=\"sr-only\"> (نئے ٹیب میں کھلتا ہے)</span></a> · <a href=\"https://www.checkbooknyc.com/data-feeds/api\" target=\"_blank\" rel=\"noopener noreferrer\">Checkbook NYC API<span class=\"sr-only\"> (نئے ٹیب میں کھلتا ہے)</span></a> · <a href=\"https://data.cityofnewyork.us/City-Government/Citywide-Payroll-Data-Fiscal-Year-/k397-673e\" target=\"_blank\" rel=\"noopener noreferrer\">شہر بھر کی تنخواہ کا ڈیٹا<span class=\"sr-only\"> (نئے ٹیب میں کھلتا ہے)</span></a> · <a href=\"https://data.cityofnewyork.us/resource/vx8i-nprf\" target=\"_blank\" rel=\"noopener noreferrer\">سول سروس فہرست<span class=\"sr-only\"> (opens in new tab)</span></a> · <a href=\"https://data.cityofnewyork.us/City-Government/Zoning-Application-Portal-ZAP-Project-Data/hgx4-8ukb\" target=\"_blank\" rel=\"noopener noreferrer\">ZAP<span class=\"sr-only\"> (نئے ٹیب میں کھلتا ہے)</span></a>۔",
